"""Enumerate subgroups of a stabilizer group (json list of (M,b)) generated by 1 or 2 elements,
deduplicated by element set (not by conjugacy). Writes sym.py --family file input.
Usage: python subgroups.py stab.json q out.json [maxorder] [npairs]"""
import json, sys, itertools, random
from geom import AG
from sym import perm_of

def closure(gens, n):
    ident = tuple(range(n)); seen = {ident}; stack = [ident]
    while stack:
        g = stack.pop()
        for h in gens:
            k = tuple(h[i] for i in g)
            if k not in seen: seen.add(k); stack.append(k)
    return frozenset(seen)

if __name__ == "__main__":
    fn, q, out = sys.argv[1], int(sys.argv[2]), sys.argv[3]
    maxorder = int(sys.argv[4]) if len(sys.argv) > 4 else 100
    npairs = int(sys.argv[5]) if len(sys.argv) > 5 else 1500
    random.seed(0)
    ag = AG(3, q); n = len(ag.points)
    els = json.load(open(fn))
    G = [tuple(perm_of(ag, e["M"], e["b"])) for e in els]
    subs = {}
    for i, g in enumerate(G):
        H = closure([g], n)
        if 1 < len(H) <= maxorder: subs.setdefault(H, [i])
    ncyc = len(subs)
    for _ in range(npairs):
        i, j = random.sample(range(len(G)), 2)
        H = closure([G[i], G[j]], n)
        if 1 < len(H) <= maxorder: subs.setdefault(H, [i, j])
    outl = [{"name": f"stabsub:ord{len(H)}:gens{gi}", "order": len(H), "cyclic": len(gi) == 1,
             "gens": [{"M": els[g]["M"], "b": els[g]["b"]} for g in gi]} for H, gi in subs.items()]
    outl.sort(key=lambda d: d["order"])
    json.dump(outl, open(out, "w"))
    from collections import Counter
    print(ncyc, "cyclic;", len(outl), "subgroups by order:", sorted(Counter(d["order"] for d in outl).items()), file=sys.stderr)
